package com.unitepaintball.app;

import android.Manifest;
import android.app.Activity;
import android.app.DownloadManager;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.graphics.Bitmap;
import android.net.Uri;
import android.os.Bundle;
import android.os.Environment;
import android.print.PrintManager;
import android.view.View;
import android.webkit.*;
import android.widget.*;
import com.google.zxing.integration.android.IntentIntegrator;
import com.google.zxing.integration.android.IntentResult;
import org.json.JSONObject;
import java.util.ArrayList;
import java.util.concurrent.atomic.AtomicInteger;

/** Écrans métier partagés, dans l'application, sans copier les données ni réduire leurs actions. */
public final class SharedFeatureActivity extends Activity {
 private WebView web;private TextView status;private Button retry;private ProgressBar progress;
 private ValueCallback<Uri[]> chooser;private PermissionRequest media;
 private byte[] fileBytes;
 private String lastUrl,scanUrl;private boolean failed,scanning;
 @Override public void onCreate(Bundle state){super.onCreate(state);AppUiPrefs.applyWindow(this);lastUrl=AppConfig.BASE_URL+SharedFeaturePolicy.path(getIntent().getStringExtra("path"));
 LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(AppUiPrefs.bg(this));LinearLayout bar=new LinearLayout(this);bar.setOrientation(LinearLayout.HORIZONTAL);
 Button back=button("‹ Retour",()->{if(web.canGoBack())web.goBack();else finish();}),home=button("Tous les outils",()->web.loadUrl(AppConfig.BASE_URL+"/fonctionnalites")),print=button("Imprimer",()->{PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print("Unité Paintball",web.createPrintDocumentAdapter("Unité Paintball"),null);});
 bar.addView(back,new LinearLayout.LayoutParams(0,-2,1));bar.addView(home,new LinearLayout.LayoutParams(0,-2,1));bar.addView(print,new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);
 status=new TextView(this);status.setTextColor(AppUiPrefs.muted(this));status.setPadding(dp(12),dp(4),dp(12),dp(4));status.setText("Connexion aux outils Unité Paintball…");root.addView(status);
 progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));
 retry=button("Réessayer le chargement",()->{failed=false;retry.setVisibility(View.GONE);web.setVisibility(View.VISIBLE);web.loadUrl(lastUrl);});retry.setVisibility(View.GONE);root.addView(retry);
 web=new WebView(this);web.setBackgroundColor(AppUiPrefs.bg(this));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);s.setUserAgentString(s.getUserAgentString()+" UnitePaintball-Android/"+AppConfig.APP_VERSION);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
 web.addJavascriptInterface(new Object(){@JavascriptInterface public void saveFile(String name,String dataUrl){runOnUiThread(()->{if(fileBytes!=null||!SharedFeaturePolicy.ownUrl(web.getUrl(),AppConfig.BASE_URL))return;try{if(dataUrl.length()>90*1024*1024)throw new IllegalArgumentException("Fichier trop volumineux");int comma=dataUrl.indexOf(',');if(comma<0||!dataUrl.substring(0,comma).endsWith(";base64"))throw new IllegalArgumentException("Fichier invalide");fileBytes=android.util.Base64.decode(dataUrl.substring(comma+1),android.util.Base64.DEFAULT);String mime=dataUrl.substring(5,comma-7);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime.isEmpty()?"application/octet-stream":mime);i.putExtra(Intent.EXTRA_TITLE,name.replaceAll("[^a-zA-Z0-9._-]","_"));startActivityForResult(i,503);}catch(Exception e){fileBytes=null;status.setText("Enregistrement impossible : "+e.getMessage());}});}@JavascriptInterface public void scanQr(){runOnUiThread(()->{if(scanning||!SharedFeaturePolicy.ownUrl(web.getUrl(),AppConfig.BASE_URL))return;scanning=true;scanUrl=web.getUrl();IntentIntegrator i=new IntentIntegrator(SharedFeatureActivity.this);i.setDesiredBarcodeFormats(IntentIntegrator.QR_CODE);i.setPrompt("Scanner le QR Unité Paintball");i.setBeepEnabled(true);i.setOrientationLocked(true);i.initiateScan();});}},"UniteNative");
 web.setWebViewClient(new WebViewClient(){
  @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String url=r.getUrl().toString();if(SharedFeaturePolicy.ownUrl(url,AppConfig.BASE_URL))return false;Uri u=r.getUrl();if("https".equals(u.getScheme())||"http".equals(u.getScheme())||"tel".equals(u.getScheme())||"mailto".equals(u.getScheme())){try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){status.setText("Lien externe indisponible.");}}return true;}
  @Override public void onPageStarted(WebView v,String url,Bitmap icon){failed=false;progress.setVisibility(View.VISIBLE);status.setText("Chargement…");if(SharedFeaturePolicy.ownUrl(url,AppConfig.BASE_URL))lastUrl=url;}
  @Override public void onPageFinished(WebView v,String url){progress.setVisibility(View.GONE);if(failed)return;status.setText("Site et application · mêmes outils et données");CookieManager.getInstance().flush();String cookie=CookieManager.getInstance().getCookie(AppConfig.BASE_URL);if(SharedFeaturePolicy.ownUrl(url,AppConfig.BASE_URL)&&cookie!=null&&!cookie.isEmpty())new SessionStore(SharedFeatureActivity.this).saveToken(cookie);}
  @Override public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())failure("Chargement interrompu. Vérifie le réseau puis réessaie.");}
  @Override public void onReceivedHttpError(WebView v,WebResourceRequest r,WebResourceResponse e){if(r.isForMainFrame()&&e.getStatusCode()>=500)failure("Le serveur est temporairement indisponible.");}
 });
 web.setWebChromeClient(new WebChromeClient(){
  @Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams p){if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;try{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");String[] types=SharedFeaturePolicy.mimeTypes(p.getAcceptTypes());if(types!=null&&types.length>0)intent.putExtra(Intent.EXTRA_MIME_TYPES,types);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,p.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);startActivityForResult(intent,501);return true;}catch(Exception e){chooser.onReceiveValue(null);chooser=null;return false;}}
  @Override public void onPermissionRequest(PermissionRequest request){runOnUiThread(()->{if(!SharedFeaturePolicy.ownUrl(request.getOrigin().toString(),AppConfig.BASE_URL)){request.deny();return;}if(media!=null)media.deny();media=request;ArrayList<String> needed=new ArrayList<>();for(String resource:request.getResources()){if(PermissionRequest.RESOURCE_VIDEO_CAPTURE.equals(resource)&&checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)needed.add(Manifest.permission.CAMERA);else if(PermissionRequest.RESOURCE_AUDIO_CAPTURE.equals(resource)&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)needed.add(Manifest.permission.RECORD_AUDIO);}if(needed.isEmpty())grantMedia();else requestPermissions(needed.toArray(new String[0]),502);});}
  @Override public void onPermissionRequestCanceled(PermissionRequest r){if(media==r)media=null;}
 });
 web.setDownloadListener((url,agent,disposition,mime,length)->{if(url.startsWith("blob:"+AppConfig.BASE_URL+"/")&&SharedFeaturePolicy.ownUrl(web.getUrl(),AppConfig.BASE_URL)){String name=URLUtil.guessFileName(url,disposition,mime);web.evaluateJavascript("fetch("+JSONObject.quote(url)+").then(r=>r.blob()).then(b=>{let reader=new FileReader();reader.onload=()=>UniteNative.saveFile("+JSONObject.quote(name)+",reader.result);reader.readAsDataURL(b);}).catch(()=>{});",null);return;}if(!SharedFeaturePolicy.ownUrl(url,AppConfig.BASE_URL)){status.setText("Téléchargement externe : utilise son lien dans le navigateur.");return;}try{String name=URLUtil.guessFileName(url,disposition,mime);DownloadManager.Request r=new DownloadManager.Request(Uri.parse(url));r.setTitle(name);r.setMimeType(mime);r.addRequestHeader("Cookie",CookieManager.getInstance().getCookie(AppConfig.BASE_URL));r.addRequestHeader("User-Agent",agent);r.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);r.setDestinationInExternalFilesDir(this,Environment.DIRECTORY_DOWNLOADS,name);((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(r);status.setText("Téléchargement lancé : "+name);}catch(Exception e){status.setText("Téléchargement impossible : "+e.getMessage());}});
 root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);AppUiPrefs.applySafeArea(root);
 String token=new SessionStore(this).token();if(token.isEmpty()){web.loadUrl(lastUrl);}else{String[] cookies=token.split(";");AtomicInteger count=new AtomicInteger(cookies.length);for(String cookie:cookies)CookieManager.getInstance().setCookie(AppConfig.BASE_URL,cookie.trim()+"; Path=/; Secure",ok->{if(count.decrementAndGet()==0){CookieManager.getInstance().flush();web.loadUrl(lastUrl);}});}
 }
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private Button button(String title,Runnable run){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(12);b.setTextColor(AppUiPrefs.text(this));b.setMinHeight(dp(48));b.setOnClickListener(v->run.run());return b;}
 private void failure(String message){failed=true;status.setText(message);progress.setVisibility(View.GONE);web.setVisibility(View.GONE);retry.setVisibility(View.VISIBLE);}
 private void grantMedia(){if(media==null)return;ArrayList<String> approved=new ArrayList<>();for(String r:media.getResources()){if(PermissionRequest.RESOURCE_VIDEO_CAPTURE.equals(r)&&checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)approved.add(r);if(PermissionRequest.RESOURCE_AUDIO_CAPTURE.equals(r)&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)approved.add(r);}if(approved.isEmpty())media.deny();else media.grant(approved.toArray(new String[0]));media=null;}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==502)grantMedia();}
 @Override protected void onActivityResult(int code,int result,Intent data){if(code==503){byte[] bytes=fileBytes;fileBytes=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&bytes!=null){Uri target=data.getData();new Thread(()->{try(java.io.OutputStream out=getContentResolver().openOutputStream(target)){if(out==null)throw new java.io.IOException("Destination inaccessible");out.write(bytes);runOnUiThread(()->status.setText("Fichier enregistré"));}catch(Exception e){runOnUiThread(()->status.setText("Enregistrement impossible : "+e.getMessage()));}}).start();}return;}if(code==501){if(chooser!=null){ArrayList<Uri> uris=new ArrayList<>();if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());}chooser.onReceiveValue(uris.isEmpty()?null:uris.toArray(new Uri[0]));chooser=null;}return;}IntentResult r=IntentIntegrator.parseActivityResult(code,result,data);if(r!=null){scanning=false;if(scanUrl!=null&&scanUrl.equals(web.getUrl())){try{JSONObject payload=new JSONObject().put("code",r.getContents()==null?"":r.getContents()).put("cancelled",r.getContents()==null);web.evaluateJavascript("window.dispatchEvent(new CustomEvent('unite-native-qr',{detail:"+payload.toString()+"}));",null);}catch(Exception ignored){}}return;}super.onActivityResult(code,result,data);}
 @Override protected void onDestroy(){if(chooser!=null)chooser.onReceiveValue(null);if(media!=null)media.deny();if(web!=null){web.removeJavascriptInterface("UniteNative");web.destroy();}super.onDestroy();}
}
